import{_ as e,o as n,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Kế hoạch kiểm chứng — DEV VERIFIED / release gates còn mở","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-crawler-management/test.md","filePath":"feature/admin-crawler-management/test.md"}'),a={name:"feature/admin-crawler-management/test.md"};function o(h,t,c,l,d,s){return n(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="ke-hoach-kiem-chung-—-dev-verified-release-gates-con-mo" tabindex="-1">Kế hoạch kiểm chứng — DEV VERIFIED / release gates còn mở <a class="header-anchor" href="#ke-hoach-kiem-chung-—-dev-verified-release-gates-con-mo" aria-label="Permalink to &quot;Kế hoạch kiểm chứng — DEV VERIFIED / release gates còn mở&quot;">​</a></h1><p>Dev dùng fixture session giả, provider mock, queue/DB cô lập. Không commit file cookie thật, không tự gọi provider trả phí hoặc ghi live trong QA. Đây là acceptance/integration/security scenarios; không viết unit test chỉ lặp lại implementation.</p><table tabindex="0"><thead><tr><th>Case</th><th>BA</th><th>Kết quả cần chứng minh</th></tr></thead><tbody><tr><td>T01</td><td>18</td><td>Existing Admin được phép; non-admin/anonymous/internal key sai bị chặn ở backend; không tạo account/role.</td></tr><tr><td>T02</td><td>02,03</td><td>Thiếu browser + session + worker đồng thời hiển thị đủ; check lỗi không che check khác; timestamp cũ là stale/unknown.</td></tr><tr><td>T03</td><td>03,10</td><td>Scheduler dừng không chặn manual đủ điều kiện; schedule enabled nhưng không heartbeat không báo healthy.</td></tr><tr><td>T04</td><td>04</td><td>TikTok thiếu key không chặn run Facebook-only; chọn TikTok phải giải thích blocker, không silently skip.</td></tr><tr><td>T05</td><td>05</td><td>JSON hỏng, quá size, domain sai, cookie shape/type sai, filename traversal đều bị từ chối; bản active cũ không đổi.</td></tr><tr><td>T06</td><td>05,18</td><td>Upload/probe/status/error/audit/log/frontend cache không chứa cookie/key; CSRF/rate limit/access control phù hợp cơ chế auth.</td></tr><tr><td>T07</td><td>06,08</td><td>Probe phân biệt login/checkpoint/proxy timeout/provider auth và unknown; static polling không phát sinh external call.</td></tr><tr><td>T08</td><td>07,19</td><td>Replace/revoke lúc run hoạt động: run hiện tại giữ version, run sau đổi version; browser ghi cookie không sửa upload gốc.</td></tr><tr><td>T09</td><td>07,18</td><td>Secret ciphertext không đọc được nếu thiếu khóa; file decrypt quyền tối thiểu; retention không xóa version còn tham chiếu.</td></tr><tr><td>T10</td><td>08,09</td><td>Chặn endpoint nội bộ/metadata IP và redirect không được phép; proxy lỗi không tự direct; key chỉ replace, không read-back.</td></tr><tr><td>T11</td><td>10</td><td>Đúng timezone/next 3 fires; giữ cron custom; migration lịch UTC không tự đổi giờ chạy; pause không hủy active run.</td></tr><tr><td>T12</td><td>11</td><td>Manual đồng thời/scheduler/API nhiều process chỉ tạo 1 run; retry request không duplicate; preview không start.</td></tr><tr><td>T13</td><td>11,12</td><td>Test nhỏ không ghi live; run thật dùng cùng pipeline và snapshot; không mock success hoặc fake progress %.</td></tr><tr><td>T14</td><td>12</td><td>Worker disconnect/failed batch/resolution failure phản ánh QUEUED/PARTIAL/FAILED đúng; DB success + cache failure không COMPLETED.</td></tr><tr><td>T15</td><td>13</td><td>Stop khi starting/crawling/queued/processing: không nhận nguồn mới, giữ dữ liệu, manifest closure đúng, downstream đã nhận tiếp tục; race hoàn thành xử lý idempotent.</td></tr><tr><td>T16</td><td>14</td><td>Fault chứa secret trong exception/proxy URL bị redaction; log pagination bounded; correlation theo run/source đúng.</td></tr><tr><td>T17</td><td>15,19</td><td>Recreate container vẫn có config/session/history/manifest; interrupted recovery không crawl lại/publish trùng; mất artifact có lỗi rõ.</td></tr><tr><td>T19</td><td>19</td><td>Concurrent admin save gây 409; không mất thay đổi form khi polling; partial disk write không làm hỏng active config.</td></tr><tr><td>T20</td><td>UI</td><td>vi/en key parallel, text không tràn; light/dark tương phản đúng; keyboard/focus/role alert và mobile/tablet/desktop hoạt động.</td></tr><tr><td>T21</td><td>Deploy</td><td>Image không chứa session/env; dependency/browser launch non-root, worker/scheduler heartbeat; startup không tải browser/cài package. Rollback không xóa volume.</td></tr><tr><td>T22</td><td>16,20</td><td>Nếu P1 được duyệt: selective retry preview + idempotency; cảnh báo đúng threshold, không spam hoặc gửi thông tin ra ngoài app.</td></tr></tbody></table><p>Không dùng kết quả production trước đây thay thế các test này. Live smoke/crawl chỉ chạy sau khi được phép triển khai và thực thi cụ thể.</p><h2 id="bang-chung-đa-chay-ngay-2026-11-02" tabindex="-1">Bằng chứng đã chạy ngày 2026-11-02 <a class="header-anchor" href="#bang-chung-đa-chay-ngay-2026-11-02" aria-label="Permalink to &quot;Bằng chứng đã chạy ngày 2026-11-02&quot;">​</a></h2><ul><li><p>AI: <code>flake8 app tests/unit</code> đạt; 23 tests trong test_crawler_credentials, test_crawler_management, test_source_config, test_trend_schedule_ownership, test_trend_persistence_failure đạt. Có 2 deprecation warnings từ datetime.utcnow hiện có.</p></li><li><p>Business: 9 tests thuộc AdminCrawlerManagementControllerTest, AiServiceSecretTransportTest, AiTrendControllerTest đạt; bao gồm role guard trước đọc body, giới hạn upload và chặn HTTP non-loopback.</p></li><li><p>Web: <code>npm run ci</code> đạt (lint không có errors, 188 warnings của repo; type-check và production build đạt). 127 key crawler vi/en song song.</p></li><li><p>Playwright CLI với API fixture và chặn mọi outbound request thật: vi/en, dark/light, desktop/mobile 390px, không overflow, preview nhỏ 1 nguồn × 2 bài và đóng modal bằng Escape. Ảnh QA nằm trong <code>brandhub-web/output/playwright/crawler-*.png</code> (artifact local, không commit). Console chỉ có tài nguyên fonts/analytics bên ngoài bị chủ động chặn.</p></li><li><p>Docker local: build <code>brandhub-ai-crawler:dev-review</code> đạt; launch browser non-root UID 1000 với network none, đọc title trang data offline đạt; assert không có /app/.env và hai file session thật trong image.</p></li><li><p>Persistence smoke: hai container mới dùng một volume QA và key fixture mount read-only; credential được mã hóa, config và history giữ nguyên qua recreation. Volume và key QA đã xóa sau test.</p></li><li><p>Bài thử đầu dùng Page.set_content chờ load timeout; browser smoke chính thức dùng navigation data với domcontentloaded như collector thực tế và đạt. Không dùng kết quả timeout đó làm bằng chứng thành công.</p></li><li><p>Chưa xác minh TLS production, provider login/proxy thực, live worker processing, screen reader thiết bị hoặc deploy/rollback thực tế. Không chạy paid providers hoặc thao tác production trong đợt này.</p></li><li><p>Browser readiness local: test thiếu package, thiếu binary, timeout, executable lỗi và cache browser có sẵn; xác minh bằng venv service thật mà không crawl hoặc gọi provider.</p></li></ul><h2 id="regression-proxy-runtime-docker" tabindex="-1">Regression proxy runtime Docker <a class="header-anchor" href="#regression-proxy-runtime-docker" aria-label="Permalink to &quot;Regression proxy runtime Docker&quot;">​</a></h2><ul><li>Không có .env: provider giả trả proxy mới, child/browser đầu tiên dùng đúng proxy mới và không tạo file.</li><li>Retry browser lấy lại proxy bằng resolver, thay proxy cũ; lỗi refresh không tiếp tục các source còn lại, giữ kết quả đã thu thập.</li><li>Provider HTTP/lỗi dữ liệu và TCP timeout trả mã lỗi an toàn; không fallback âm thầm sang proxy cũ hoặc direct.</li><li>--proxy, --no-proxy và proxy quản lý cố định không gọi API xoay; Threads nhận proxy runtime và không đọc lại dotenv.</li><li>Không log endpoint, mật khẩu, API key; dùng mock, không thay production.</li></ul><p>Kết quả dev: 45 test crawler đạt; thêm test giới hạn retry proxy cố định và chạy lại 15/15 test proxy runtime đạt. Regression AI API/crawler 35/35 đạt; flake8 đạt. Provider/socket/browser đều được giả lập, không chạy crawl thật hoặc deploy production.</p><h2 id="session-ram-theo-yeu-cau-2026-11-02" tabindex="-1">Session RAM theo yêu cầu (2026-11-02) <a class="header-anchor" href="#session-ram-theo-yeu-cau-2026-11-02" aria-label="Permalink to &quot;Session RAM theo yêu cầu (2026-11-02)&quot;">​</a></h2><p>Upload không key thành công, metadata không chứa cookie; store mới cùng process đọc được, process mới mất session. Run chụp session cũ trước replace/revoke và stdin tới browser dùng dict không ghi file. Thiếu session chặn start. Probe/legacy cookie API không ghi session file hoặc Redis. Kiểm tra song ngữ, dark/light và npm run ci.</p><p>Kết quả session RAM: 55 test crawler/IPC/browser/proxy đạt; 37 test AI API/crawler đạt, sau chỉnh cache chạy lại 17 test liên quan đạt; flake8 và Web npm run ci đạt (188 cảnh báo lint hiện có, không lỗi). Preflight thực tế cho Facebook/Threads đọc RAM qua stdin đạt. UI fixture vi/en, light/dark, mobile 390px, file input không key và keyboard focus đạt. Không gọi provider thật, không chạy crawl thật, không deploy.</p><h2 id="deploy-disk-guard-2026-11-02" tabindex="-1">Deploy disk guard (2026-11-02) <a class="header-anchor" href="#deploy-disk-guard-2026-11-02" aria-label="Permalink to &quot;Deploy disk guard (2026-11-02)&quot;">​</a></h2><p>Giữ image mọi container, foreign/shared tags, target và một rollback; cleanup chỉ repo AI không force và không volume/container prune. Thiếu disk/inode sau cleanup trả lỗi trước deploy. Dry-run không mutate. Chạy unit tests mock Docker và parse workflow; chỉ inventory/dry-run production.</p><p>Disk guard: 6 unit test đạt, flake8 đạt; YAML và command base64/argparse/order được kiểm tra. Production dry-run chỉ đọc chọn 8 image AI cũ (10 tag), giữ image đang chạy và sha-f435746-20 dự phòng. Disk trống 2.21 GiB nên guard báo ready=false. Chưa chạy --apply, chưa push/deploy.</p><h2 id="sua-quyen-volume-va-chan-đoan-rollback-2026-11-02" tabindex="-1">Sửa quyền volume và chẩn đoán rollback (2026-11-02) <a class="header-anchor" href="#sua-quyen-volume-va-chan-đoan-rollback-2026-11-02" aria-label="Permalink to &quot;Sửa quyền volume và chẩn đoán rollback (2026-11-02)&quot;">​</a></h2><p>Volume parent root:755 vẫn giữ nguyên; control/output thuộc appuser và ghi được. Chạy init lần hai không đổi dữ liệu; không theo symlink/hardlink ra ngoài. Init failure không recreate service. Startup failure capture health/log trước compose restore, che env secrets/cookie/URL. Test Docker offline với volume giả, không mount production.</p><p>Kết quả dev: 12 unit test disk/volume/diagnostics đạt; flake8 và YAML/Bash/command SSM sau giải mã đạt. Docker local volume giả root:755 tái hiện lỗi trước init; sau init appuser UID1000 ghi được scheduler lock/heartbeat/output, dữ liệu cũ giữ nguyên, parent/other-service không đổi. Init lần hai đạt; volume QA đã xóa. Chưa đổi production, chưa commit/push/deploy.</p><h2 id="retention-khi-rollout-that-bai-2026-11-02" tabindex="-1">Retention khi rollout thất bại (2026-11-02) <a class="header-anchor" href="#retention-khi-rollout-that-bai-2026-11-02" aria-label="Permalink to &quot;Retention khi rollout thất bại (2026-11-02)&quot;">​</a></h2><p>Regression: active image cũ + failed image mới + previous image cũ hơn =&gt; cleanup failed, giữ active/previous. Target mới được giữ; không có active image vẫn giữ một unused. Dry-run không mutate. Đối chiếu production sha-6060fc3-25 unused, unique4.063GB; không hạ disk guard.</p><p>Kết quả: 16 test disk/volume/diagnostics đạt, flake8 đạt. Production dry-run mới chỉ chọn sha-6060fc3-25 (unused, 4.063GB unique), giữ current sha-0ed93a6-21 và không sửa/xóa dữ liệu. Disk hiện vẫn5.57GiB vì chưa apply; ngưỡng6GiB không đổi. Chưa commit/push/deploy.</p><h2 id="kiem-tra-overview-rut-gon-2026-11-02" tabindex="-1">Kiểm tra overview rút gọn (2026-11-02) <a class="header-anchor" href="#kiem-tra-overview-rut-gon-2026-11-02" aria-label="Permalink to &quot;Kiểm tra overview rút gọn (2026-11-02)&quot;">​</a></h2><p>Nhiều history không theo thứ tự: chỉ run startedAt mới nhất hiện. Active ưu tiên hơn history. Khi latest completed/failed vẫn hiện; latest interrupted giữ recovery. Không có run thì ẩn banner. Tab lịch sử giữ mọi run. Kiểm tra vi/en, light/dark, mobile và keyboard với fixture, không chạy crawler thật.</p><p>Kết quả: npm run ci pass (188 warning có sẵn, 0 error); Playwright fixture vi/en pass cho active, completed, failed, interrupted, lịch sử đầy đủ và empty; screenshot light/dark/mobile đã kiểm tra.</p><h2 id="thu-muc-worker-co-quyen-ghi-2026-11-03" tabindex="-1">Thư mục worker có quyền ghi (2026-11-03) <a class="header-anchor" href="#thu-muc-worker-co-quyen-ghi-2026-11-03" aria-label="Permalink to &quot;Thư mục worker có quyền ghi (2026-11-03)&quot;">​</a></h2><p>Kiểm tra volume /app/data root:root 0755: trước init UID1000 không ghi được; sau init ghi atomic batch JSON và label_check.state tại crawler/trend_runs. Parent/ngoài crawler giữ nguyên owner/dữ liệu. Kiểm tra workflow áp TREND_RUN_DIR trước init/up, YAML/Compose hợp lệ, unit aggregation/label check pass.</p><p>Kết quả dev: flake8 pass; 18 unit tests pass; parse workflow YAML/Compose JSON và thực thi lệnh cập nhật Compose trên fixture pass, environment khác giữ nguyên. Smoke Docker chưa chạy được do Docker daemon local tắt. Chưa đổi production hay replay run cũ.</p><h2 id="cai-browser-on-đinh-trong-build-2026-11-03" tabindex="-1">Cài browser ổn định trong build (2026-11-03) <a class="header-anchor" href="#cai-browser-on-đinh-trong-build-2026-11-03" aria-label="Permalink to &quot;Cài browser ổn định trong build (2026-11-03)&quot;">​</a></h2><p>Installer phải truyền phiên bản chính xác vào ensure_binary, kiểm tra path tồn tại/executable và surface lỗi download. Unit CI đầy đủ phải pass. Build không bỏ qua diagnostic hoặc lỗi cài đặt; kiểm tra YAML và Docker build nếu daemon hoạt động.</p><p>Kết quả: full flake8 pass; full pytest tests/unit với junit + coverage: 995 passed, 128 warning có sẵn. Workflow YAML và Docker layer order pass. Docker build Linux chưa chạy được do Linux Engine local không hoạt động, dù đã thử khởi động Docker Desktop. Crash exit 139 do thread teardown là giả thuyết từ log và nhánh installer upstream; chưa có faulthandler trace từ build lỗi để khẳng định.</p><p>Bổ sung khi Docker đã bật: smoke Linux volume root-owned pass (UID1000, atomic batch + label-check, init 2 lần, không đổi parent). Installer pinned 5 lần không tạo background threads; Chromium mở/đóng trang offline pass trong image cache cùng CloakBrowser 0.5.10. Full Dockerfile build đang kiểm tra. Đã loại data/crawler khỏi build context và đặt runtime ENV sau dependency layers.</p><p>Kết quả cuối khi Docker bật: full Dockerfile build exit 0, pinned installer và info --quick pass (không exit139); image brandhub-ai-crawler:browser-fix-review. Final-image offline smoke: UID1000, TREND_RUN_DIR đúng, không chứa .env/session; 5 lần ensure_binary pinned không có update thread, Chromium page launch/close pass. Worker volume smoke dùng code trong image (không bind dev source) pass, volume QA đã xóa. Build lặp lại sử dụng cache: exit0 trong 4.8 giây. Chưa push/deploy.</p><h2 id="gioi-han-ram-ai-4-5-gib-2026-11-03" tabindex="-1">Giới hạn RAM AI 4.5 GiB (2026-11-03) <a class="header-anchor" href="#gioi-han-ram-ai-4-5-gib-2026-11-03" aria-label="Permalink to &quot;Giới hạn RAM AI 4.5 GiB (2026-11-03)&quot;">​</a></h2><p>Render Compose xác nhận ai-service.mem_limit tương đương 4831838208 bytes. Thực thi generated compose updater trên fixture 2300m: đổi thành 4608m, giữ env khác và memory service khác. YAML hợp lệ, CI flake8/unit pass. Production chỉ nhận cấu hình khi deploy; chưa restart hay retry run.</p><p>Kết quả: Compose base và base+overlay render 4608m (4.5 GiB); generated updater áp memory mới và giữ env/limit service khác. Full flake8 pass, pytest unit 995 passed (128 warning có sẵn). Chưa commit/push/deploy, production chưa đổi.</p>',35)])])}const p=e(a,[["render",o]]);export{g as __pageData,p as default};
